contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public { c = new Owned(); admin = address(this); }

    function testFuzz_property(address newOwner) public {
        vm.prank(admin);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) { ok = success; } catch { ok = false; }

        assertTrue(ok && c.owner() == newOwner);
    }
}
